 $invalid=$data;$invalid['orden_lstservicios']=json_encode([[1,'Consultoría fracción','Servicio profesional',60,1.5,0,90]]);$invalid['orden_totcompra']=90;$invalid['orden_igv']=16.2;$invalid['orden_totneto']=106.2;[$status]=$http->request('/modules/ordenes/insert-update-orden.php',$invalid);serviceAssert($status===422,'El servidor aceptó una cantidad fraccionaria.');serviceAssert((float)$pdo->query('SELECT total_purchase FROM tbl_order WHERE id='.$order)->fetchColumn()===120.0,'Un fallo alteró la OS guardada.');
